export const FAMILY_MP: NistCatalogFamily = {"code":"MP","name":"Media Protection","controls":[{"id":"MP-1","oscal_id":"mp-1","family":"MP","title":"Policy and Procedures","statement":"a. Develop, document, and disseminate to <organization-defined personnel or roles>:\n  Develop, document, and disseminate to <organization-defined personnel or roles>:\n  1. <organization-defined parameter> media protection policy that:\n    <organization-defined parameter> media protection policy that:\n    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and\n    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and\n  2. Procedures to facilitate the implementation of the media protection policy and the associated media protection controls;\nb. Designate an <official> to manage the development, documentation, and dissemination of the media protection policy and procedures; and\nc. Review and update the current media protection:\n  Review and update the current media protection:\n  1. Policy <frequency> and following <events> ; and\n  2. Procedures <frequency> and following <events>.","supplemental_guidance":"Media protection policy and procedures address the controls in the MP family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of media protection policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to media protection policy and procedures include assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure.","implementation_level":"organization","parameters":[{"id":"mp-1_prm_1","label":"organization-defined personnel or roles"},{"id":"mp-01_odp.01","label":"personnel or roles"},{"id":"mp-01_odp.02","label":"personnel or roles"},{"id":"mp-01_odp.03","label":"","choices":["organization-level","mission/business process-level","system-level"],"how_many":"one-or-more"},{"id":"mp-01_odp.04","label":"official"},{"id":"mp-01_odp.05","label":"frequency"},{"id":"mp-01_odp.06","label":"events"},{"id":"mp-01_odp.07","label":"frequency"},{"id":"mp-01_odp.08","label":"events"}],"objectives":[{"id":"mp-1_obj.a-1","label":"MP-01a.[01]","text":"a media protection policy is developed and documented;"},{"id":"mp-1_obj.a-2","label":"MP-01a.[02]","text":"the media protection policy is disseminated to {{ insert: param, mp-01_odp.01 }};"},{"id":"mp-1_obj.a-3","label":"MP-01a.[03]","text":"media protection procedures to facilitate the implementation of the media protection policy and associated media protection controls are developed and documented;"},{"id":"mp-1_obj.a-4","label":"MP-01a.[04]","text":"the media protection procedures are disseminated to {{ insert: param, mp-01_odp.02 }};"},{"id":"mp-1_obj.a.1.a-1","label":"MP-01a.01(a)[01]","text":"the {{ insert: param, mp-01_odp.03 }} media protection policy addresses purpose;"},{"id":"mp-1_obj.a.1.a-2","label":"MP-01a.01(a)[02]","text":"the {{ insert: param, mp-01_odp.03 }} media protection policy addresses scope;"},{"id":"mp-1_obj.a.1.a-3","label":"MP-01a.01(a)[03]","text":"the {{ insert: param, mp-01_odp.03 }} media protection policy addresses roles;"},{"id":"mp-1_obj.a.1.a-4","label":"MP-01a.01(a)[04]","text":"the {{ insert: param, mp-01_odp.03 }} media protection policy addresses responsibilities;"},{"id":"mp-1_obj.a.1.a-5","label":"MP-01a.01(a)[05]","text":"the {{ insert: param, mp-01_odp.03 }} media protection policy addresses management commitment;"},{"id":"mp-1_obj.a.1.a-6","label":"MP-01a.01(a)[06]","text":"the {{ insert: param, mp-01_odp.03 }} media protection policy addresses coordination among organizational entities;"},{"id":"mp-1_obj.a.1.a-7","label":"MP-01a.01(a)[07]","text":"the {{ insert: param, mp-01_odp.03 }} media protection policy compliance;"},{"id":"mp-1_obj.a.1.b","label":"MP-01a.01(b)","text":"the media protection policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"},{"id":"mp-1_obj.b","label":"MP-01b.","text":"the {{ insert: param, mp-01_odp.04 }} is designated to manage the development, documentation, and dissemination of the media protection policy and procedures."},{"id":"mp-1_obj.c.1-1","label":"MP-01c.01[01]","text":"the current media protection policy is reviewed and updated {{ insert: param, mp-01_odp.05 }};"},{"id":"mp-1_obj.c.1-2","label":"MP-01c.01[02]","text":"the current media protection policy is reviewed and updated following {{ insert: param, mp-01_odp.06 }};"},{"id":"mp-1_obj.c.2-1","label":"MP-01c.02[01]","text":"the current media protection procedures are reviewed and updated {{ insert: param, mp-01_odp.07 }};"},{"id":"mp-1_obj.c.2-2","label":"MP-01c.02[02]","text":"the current media protection procedures are reviewed and updated following {{ insert: param, mp-01_odp.08 }}."}],"methods":[{"method":"examine","label":"MP-01-Examine"},{"method":"interview","label":"MP-01-Interview"}],"references":[{"title":"OMB A-130"},{"title":"SP 800-12"},{"title":"SP 800-30"},{"title":"SP 800-39"},{"title":"SP 800-100"}],"related_controls":["PM-9","PS-8","SI-12"]},{"id":"MP-2","oscal_id":"mp-2","family":"MP","title":"Media Access","statement":"Restrict access to <organization-defined types of digital and/or non-digital media> to <organization-defined personnel or roles>.","supplemental_guidance":"System media includes digital and non-digital media. Digital media includes flash drives, diskettes, magnetic tapes, external or removable hard disk drives (e.g., solid state, magnetic), compact discs, and digital versatile discs. Non-digital media includes paper and microfilm. Denying access to patient medical records in a community hospital unless the individuals seeking access to such records are authorized healthcare providers is an example of restricting access to non-digital media. Limiting access to the design specifications stored on compact discs in the media library to individuals on the system development team is an example of restricting access to digital media.","implementation_level":"organization","parameters":[{"id":"mp-2_prm_1","label":"organization-defined types of digital and/or non-digital media"},{"id":"mp-2_prm_2","label":"organization-defined personnel or roles"},{"id":"mp-02_odp.01","label":"types of digital media"},{"id":"mp-02_odp.02","label":"personnel or roles"},{"id":"mp-02_odp.03","label":"types of non-digital media"},{"id":"mp-02_odp.04","label":"personnel or roles"}],"objectives":[{"id":"mp-2_obj-1","label":"MP-02[01]","text":"access to {{ insert: param, mp-02_odp.01 }} is restricted to {{ insert: param, mp-02_odp.02 }};"},{"id":"mp-2_obj-2","label":"MP-02[02]","text":"access to {{ insert: param, mp-02_odp.03 }} is restricted to {{ insert: param, mp-02_odp.04 }}."}],"methods":[{"method":"examine","label":"MP-02-Examine"},{"method":"interview","label":"MP-02-Interview"},{"method":"test","label":"MP-02-Test"}],"references":[{"title":"OMB A-130"},{"title":"FIPS 199"},{"title":"SP 800-111"}],"related_controls":["AC-19","AU-9","CP-2","CP-9","CP-10","MA-5","MP-4","MP-6","PE-2","PE-3","SC-12","SC-13","SC-34","SI-12"],"enhancements":[{"id":"MP-2(1)","oscal_id":"mp-2.1","family":"MP","title":"Automated Restricted Access","statement":"","is_enhancement":true,"parent_id":"MP-2"},{"id":"MP-2(2)","oscal_id":"mp-2.2","family":"MP","title":"Cryptographic Protection","statement":"","is_enhancement":true,"parent_id":"MP-2"}]},{"id":"MP-3","oscal_id":"mp-3","family":"MP","title":"Media Marking","statement":"a. Mark system media indicating the distribution limitations, handling caveats, and applicable security markings (if any) of the information; and\nb. Exempt <types of media exempted from marking> from marking if the media remain within <controlled areas>.","supplemental_guidance":"Security marking refers to the application or use of human-readable security attributes. Digital media includes diskettes, magnetic tapes, external or removable hard disk drives (e.g., solid state, magnetic), flash drives, compact discs, and digital versatile discs. Non-digital media includes paper and microfilm. Controlled unclassified information is defined by the National Archives and Records Administration along with the appropriate safeguarding and dissemination requirements for such information and is codified in [32 CFR 2002](#91f992fb-f668-4c91-a50f-0f05b95ccee3) . Security markings are generally not required for media that contains information determined by organizations to be in the public domain or to be publicly releasable. Some organizations may require markings for public information indicating that the information is publicly releasable. System media marking reflects applicable laws, executive orders, directives, policies, regulations, standards, and guidelines.","implementation_level":"organization","parameters":[{"id":"mp-03_odp.01","label":"types of media exempted from marking"},{"id":"mp-03_odp.02","label":"controlled areas"}],"objectives":[{"id":"mp-3_obj.a","label":"MP-03a.","text":"system media is marked to indicate distribution limitations, handling caveats, and applicable security markings (if any) of the information;"},{"id":"mp-3_obj.b","label":"MP-03b.","text":"{{ insert: param, mp-03_odp.01 }} remain within {{ insert: param, mp-03_odp.02 }}."}],"methods":[{"method":"examine","label":"MP-03-Examine"},{"method":"interview","label":"MP-03-Interview"},{"method":"test","label":"MP-03-Test"}],"references":[{"title":"EO 13556"},{"title":"32 CFR 2002"},{"title":"FIPS 199"}],"related_controls":["AC-16","CP-9","MP-5","PE-22","SI-12"]},{"id":"MP-4","oscal_id":"mp-4","family":"MP","title":"Media Storage","statement":"a. Physically control and securely store <organization-defined types of digital and/or non-digital media> within <organization-defined controlled areas> ; and\nb. Protect system media types defined in MP-4a until the media are destroyed or sanitized using approved equipment, techniques, and procedures.","supplemental_guidance":"System media includes digital and non-digital media. Digital media includes flash drives, diskettes, magnetic tapes, external or removable hard disk drives (e.g., solid state, magnetic), compact discs, and digital versatile discs. Non-digital media includes paper and microfilm. Physically controlling stored media includes conducting inventories, ensuring procedures are in place to allow individuals to check out and return media to the library, and maintaining accountability for stored media. Secure storage includes a locked drawer, desk, or cabinet or a controlled media library. The type of media storage is commensurate with the security category or classification of the information on the media. Controlled areas are spaces that provide physical and procedural controls to meet the requirements established for protecting information and systems. Fewer controls may be needed for media that contains information determined to be in the public domain, publicly releasable, or have limited adverse impacts on organizations, operations, or individuals if accessed by other than authorized personnel. In these situations, physical access controls provide adequate protection.","implementation_level":"organization","parameters":[{"id":"mp-4_prm_1","label":"organization-defined types of digital and/or non-digital media"},{"id":"mp-4_prm_2","label":"organization-defined controlled areas"},{"id":"mp-04_odp.01","label":"types of digital media"},{"id":"mp-04_odp.02","label":"types of non-digital media"},{"id":"mp-04_odp.03","label":"types of digital media"},{"id":"mp-04_odp.04","label":"types of non-digital media"},{"id":"mp-04_odp.05","label":"controlled areas"},{"id":"mp-04_odp.06","label":"controlled areas"}],"objectives":[{"id":"mp-4_obj.a-1","label":"MP-04a.[01]","text":"{{ insert: param, mp-04_odp.01 }} are physically controlled;"},{"id":"mp-4_obj.a-2","label":"MP-04a.[02]","text":"{{ insert: param, mp-04_odp.02 }} are physically controlled;"},{"id":"mp-4_obj.a-3","label":"MP-04a.[03]","text":"{{ insert: param, mp-04_odp.03 }} are securely stored within {{ insert: param, mp-04_odp.05 }};"},{"id":"mp-4_obj.a-4","label":"MP-04a.[04]","text":"{{ insert: param, mp-04_odp.04 }} are securely stored within {{ insert: param, mp-04_odp.06 }};"},{"id":"mp-4_obj.b","label":"MP-04b.","text":"system media types (defined in MP-04_ODP[01], MP-04_ODP[02], MP-04_ODP[03], MP-04_ODP[04]) are protected until the media are destroyed or sanitized using approved equipment, techniques, and procedures."}],"methods":[{"method":"examine","label":"MP-04-Examine"},{"method":"interview","label":"MP-04-Interview"},{"method":"test","label":"MP-04-Test"}],"references":[{"title":"FIPS 199"},{"title":"SP 800-56A"},{"title":"SP 800-56B"},{"title":"SP 800-56C"},{"title":"SP 800-57-1"},{"title":"SP 800-57-2"},{"title":"SP 800-57-3"},{"title":"SP 800-111"}],"related_controls":["AC-19","CP-2","CP-6","CP-9","CP-10","MP-2","MP-7","PE-3","PL-2","SC-12","SC-13","SC-28","SC-34","SI-12"],"enhancements":[{"id":"MP-4(1)","oscal_id":"mp-4.1","family":"MP","title":"Cryptographic Protection","statement":"","is_enhancement":true,"parent_id":"MP-4"},{"id":"MP-4(2)","oscal_id":"mp-4.2","family":"MP","title":"Automated Restricted Access","statement":"Restrict access to media storage areas and log access attempts and access granted using <organization-defined automated mechanisms>.","supplemental_guidance":"Automated mechanisms include keypads, biometric readers, or card readers on the external entries to media storage areas.","implementation_level":"organization","parameters":[{"id":"mp-4.2_prm_1","label":"organization-defined automated mechanisms"},{"id":"mp-04.02_odp.01","label":"automated mechanisms"},{"id":"mp-04.02_odp.02","label":"automated mechanisms"},{"id":"mp-04.02_odp.03","label":"automated mechanisms"}],"objectives":[{"id":"mp-4.2_obj-1","label":"MP-04(02)[01]","text":"access to media storage areas is restricted using {{ insert: param, mp-04.02_odp.01 }};"},{"id":"mp-4.2_obj-2","label":"MP-04(02)[02]","text":"access attempts to media storage areas are logged using {{ insert: param, mp-04.02_odp.02 }};"},{"id":"mp-4.2_obj-3","label":"MP-04(02)[03]","text":"access granted to media storage areas is logged using {{ insert: param, mp-04.02_odp.03 }}."}],"methods":[{"method":"examine","label":"MP-04(02)-Examine"},{"method":"interview","label":"MP-04(02)-Interview"},{"method":"test","label":"MP-04(02)-Test"}],"related_controls":["AC-3","AU-2","AU-6","AU-9","AU-12","PE-3"],"is_enhancement":true,"parent_id":"MP-4"}]},{"id":"MP-5","oscal_id":"mp-5","family":"MP","title":"Media Transport","statement":"a. Protect and control <types of system media> during transport outside of controlled areas using <organization-defined controls>;\nb. Maintain accountability for system media during transport outside of controlled areas;\nc. Document activities associated with the transport of system media; and\nd. Restrict the activities associated with the transport of system media to authorized personnel.","supplemental_guidance":"System media includes digital and non-digital media. Digital media includes flash drives, diskettes, magnetic tapes, external or removable hard disk drives (e.g., solid state and magnetic), compact discs, and digital versatile discs. Non-digital media includes microfilm and paper. Controlled areas are spaces for which organizations provide physical or procedural controls to meet requirements established for protecting information and systems. Controls to protect media during transport include cryptography and locked containers. Cryptographic mechanisms can provide confidentiality and integrity protections depending on the mechanisms implemented. Activities associated with media transport include releasing media for transport, ensuring that media enters the appropriate transport processes, and the actual transport. Authorized transport and courier personnel may include individuals external to the organization. Maintaining accountability of media during transport includes restricting transport activities to authorized personnel and tracking and/or obtaining records of transport activities as the media moves through the transportation system to prevent and detect loss, destruction, or tampering. Organizations establish documentation requirements for activities associated with the transport of system media in accordance with organizational assessments of risk. Organizations maintain the flexibility to define record-keeping methods for the different types of media transport as part of a system of transport-related records.","implementation_level":"organization","parameters":[{"id":"mp-5_prm_2","label":"organization-defined controls"},{"id":"mp-05_odp.01","label":"types of system media"},{"id":"mp-05_odp.02","label":"controls"},{"id":"mp-05_odp.03","label":"controls"}],"objectives":[{"id":"mp-5_obj.a-1","label":"MP-05a.[01]","text":"{{ insert: param, mp-05_odp.01 }} are protected during transport outside of controlled areas using {{ insert: param, mp-05_odp.02 }};"},{"id":"mp-5_obj.a-2","label":"MP-05a.[02]","text":"{{ insert: param, mp-05_odp.01 }} are controlled during transport outside of controlled areas using {{ insert: param, mp-05_odp.03 }};"},{"id":"mp-5_obj.b","label":"MP-05b.","text":"accountability for system media is maintained during transport outside of controlled areas;"},{"id":"mp-5_obj.c","label":"MP-05c.","text":"activities associated with the transport of system media are documented;"},{"id":"mp-5_obj.d-1","label":"MP-05d.[01]","text":"personnel authorized to conduct media transport activities is/are identified;"},{"id":"mp-5_obj.d-2","label":"MP-05d.[02]","text":"activities associated with the transport of system media are restricted to identified authorized personnel."}],"methods":[{"method":"examine","label":"MP-05-Examine"},{"method":"interview","label":"MP-05-Interview"},{"method":"test","label":"MP-05-Test"}],"references":[{"title":"FIPS 199"},{"title":"SP 800-60-1"},{"title":"SP 800-60-2"}],"related_controls":["AC-7","AC-19","CP-2","CP-9","MP-3","MP-4","PE-16","PL-2","SC-12","SC-13","SC-28","SC-34"],"enhancements":[{"id":"MP-5(1)","oscal_id":"mp-5.1","family":"MP","title":"Protection Outside of Controlled Areas","statement":"","is_enhancement":true,"parent_id":"MP-5"},{"id":"MP-5(2)","oscal_id":"mp-5.2","family":"MP","title":"Documentation of Activities","statement":"","is_enhancement":true,"parent_id":"MP-5"},{"id":"MP-5(3)","oscal_id":"mp-5.3","family":"MP","title":"Custodians","statement":"Employ an identified custodian during transport of system media outside of controlled areas.","supplemental_guidance":"Identified custodians provide organizations with specific points of contact during the media transport process and facilitate individual accountability. Custodial responsibilities can be transferred from one individual to another if an unambiguous custodian is identified.","implementation_level":"organization","objectives":[{"id":"mp-5.3_obj-1","label":"MP-05(03)[01]","text":"a custodian to transport system media outside of controlled areas is identified;"},{"id":"mp-5.3_obj-2","label":"MP-05(03)[02]","text":"the identified custodian is employed during the transport of system media outside of controlled areas."}],"methods":[{"method":"examine","label":"MP-05(03)-Examine"},{"method":"interview","label":"MP-05(03)-Interview"},{"method":"test","label":"MP-05(03)-Test"}],"is_enhancement":true,"parent_id":"MP-5"},{"id":"MP-5(4)","oscal_id":"mp-5.4","family":"MP","title":"Cryptographic Protection","statement":"","is_enhancement":true,"parent_id":"MP-5"}]},{"id":"MP-6","oscal_id":"mp-6","family":"MP","title":"Media Sanitization","statement":"a. Sanitize <organization-defined system media> prior to disposal, release out of organizational control, or release for reuse using <organization-defined sanitization techniques and procedures> ; and\nb. Employ sanitization mechanisms with the strength and integrity commensurate with the security category or classification of the information.","supplemental_guidance":"Media sanitization applies to all digital and non-digital system media subject to disposal or reuse, whether or not the media is considered removable. Examples include digital media in scanners, copiers, printers, notebook computers, workstations, network components, mobile devices, and non-digital media (e.g., paper and microfilm). The sanitization process removes information from system media such that the information cannot be retrieved or reconstructed. Sanitization techniques—including clearing, purging, cryptographic erase, de-identification of personally identifiable information, and destruction—prevent the disclosure of information to unauthorized individuals when such media is reused or released for disposal. Organizations determine the appropriate sanitization methods, recognizing that destruction is sometimes necessary when other methods cannot be applied to media requiring sanitization. Organizations use discretion on the employment of approved sanitization techniques and procedures for media that contains information deemed to be in the public domain or publicly releasable or information deemed to have no adverse impact on organizations or individuals if released for reuse or disposal. Sanitization of non-digital media includes destruction, removing a classified appendix from an otherwise unclassified document, or redacting selected sections or words from a document by obscuring the redacted sections or words in a manner equivalent in effectiveness to removing them from the document. NSA standards and policies control the sanitization process for media that contains classified information. NARA policies control the sanitization process for controlled unclassified information.","implementation_level":"organization","parameters":[{"id":"mp-6_prm_1","label":"organization-defined system media"},{"id":"mp-6_prm_2","label":"organization-defined sanitization techniques and procedures"},{"id":"mp-06_odp.01","label":"system media"},{"id":"mp-06_odp.02","label":"system media"},{"id":"mp-06_odp.03","label":"system media"},{"id":"mp-06_odp.04","label":"sanitization techniques and procedures"},{"id":"mp-06_odp.05","label":"sanitization techniques and procedures"},{"id":"mp-06_odp.06","label":"sanitization techniques and procedures"}],"objectives":[{"id":"mp-6_obj.a-1","label":"MP-06a.[01]","text":"{{ insert: param, mp-06_odp.01 }} is sanitized using {{ insert: param, mp-06_odp.04 }} prior to disposal;"},{"id":"mp-6_obj.a-2","label":"MP-06a.[02]","text":"{{ insert: param, mp-06_odp.02 }} is sanitized using {{ insert: param, mp-06_odp.05 }} prior to release from organizational control;"},{"id":"mp-6_obj.a-3","label":"MP-06a.[03]","text":"{{ insert: param, mp-06_odp.03 }} is sanitized using {{ insert: param, mp-06_odp.06 }} prior to release for reuse;"},{"id":"mp-6_obj.b","label":"MP-06b.","text":"sanitization mechanisms with strength and integrity commensurate with the security category or classification of the information are employed."}],"methods":[{"method":"examine","label":"MP-06-Examine"},{"method":"interview","label":"MP-06-Interview"},{"method":"test","label":"MP-06-Test"}],"references":[{"title":"32 CFR 2002"},{"title":"OMB A-130"},{"title":"NARA CUI"},{"title":"FIPS 199"},{"title":"SP 800-60-1"},{"title":"SP 800-60-2"},{"title":"SP 800-88"},{"title":"SP 800-124"},{"title":"IR 8023"},{"title":"NSA MEDIA"}],"related_controls":["AC-3","AC-7","AU-11","MA-2","MA-3","MA-4","MA-5","PM-22","SI-12","SI-18","SI-19","SR-11"],"enhancements":[{"id":"MP-6(1)","oscal_id":"mp-6.1","family":"MP","title":"Review, Approve, Track, Document, and Verify","statement":"Review, approve, track, document, and verify media sanitization and disposal actions.","supplemental_guidance":"Organizations review and approve media to be sanitized to ensure compliance with records retention policies. Tracking and documenting actions include listing personnel who reviewed and approved sanitization and disposal actions, types of media sanitized, files stored on the media, sanitization methods used, date and time of the sanitization actions, personnel who performed the sanitization, verification actions taken and personnel who performed the verification, and the disposal actions taken. Organizations verify that the sanitization of the media was effective prior to disposal.","implementation_level":"organization","objectives":[{"id":"mp-6.1_obj-1","label":"MP-06(01)[01]","text":"media sanitization and disposal actions are reviewed;"},{"id":"mp-6.1_obj-2","label":"MP-06(01)[02]","text":"media sanitization and disposal actions are approved;"},{"id":"mp-6.1_obj-3","label":"MP-06(01)[03]","text":"media sanitization and disposal actions are tracked;"},{"id":"mp-6.1_obj-4","label":"MP-06(01)[04]","text":"media sanitization and disposal actions are documented;"},{"id":"mp-6.1_obj-5","label":"MP-06(01)[05]","text":"media sanitization and disposal actions are verified."}],"methods":[{"method":"examine","label":"MP-06(01)-Examine"},{"method":"interview","label":"MP-06(01)-Interview"},{"method":"test","label":"MP-06(01)-Test"}],"is_enhancement":true,"parent_id":"MP-6"},{"id":"MP-6(2)","oscal_id":"mp-6.2","family":"MP","title":"Equipment Testing","statement":"Test sanitization equipment and procedures <organization-defined frequency> to ensure that the intended sanitization is being achieved.","supplemental_guidance":"Testing of sanitization equipment and procedures may be conducted by qualified and authorized external entities, including federal agencies or external service providers.","implementation_level":"organization","parameters":[{"id":"mp-6.2_prm_1","label":"organization-defined frequency"},{"id":"mp-06.02_odp.01","label":"frequency"},{"id":"mp-06.02_odp.02","label":"frequency"}],"objectives":[{"id":"mp-6.2_obj-1","label":"MP-06(02)[01]","text":"sanitization equipment is tested {{ insert: param, mp-06.02_odp.01 }} to ensure that the intended sanitization is being achieved;"},{"id":"mp-6.2_obj-2","label":"MP-06(02)[02]","text":"sanitization procedures are tested {{ insert: param, mp-06.02_odp.02 }} to ensure that the intended sanitization is being achieved."}],"methods":[{"method":"examine","label":"MP-06(02)-Examine"},{"method":"interview","label":"MP-06(02)-Interview"},{"method":"test","label":"MP-06(02)-Test"}],"is_enhancement":true,"parent_id":"MP-6"},{"id":"MP-6(3)","oscal_id":"mp-6.3","family":"MP","title":"Nondestructive Techniques","statement":"Apply nondestructive sanitization techniques to portable storage devices prior to connecting such devices to the system under the following circumstances: <circumstances>.","supplemental_guidance":"Portable storage devices include external or removable hard disk drives (e.g., solid state, magnetic), optical discs, magnetic or optical tapes, flash memory devices, flash memory cards, and other external or removable disks. Portable storage devices can be obtained from untrustworthy sources and contain malicious code that can be inserted into or transferred to organizational systems through USB ports or other entry portals. While scanning storage devices is recommended, sanitization provides additional assurance that such devices are free of malicious code. Organizations consider nondestructive sanitization of portable storage devices when the devices are purchased from manufacturers or vendors prior to initial use or when organizations cannot maintain a positive chain of custody for the devices.","implementation_level":"organization","parameters":[{"id":"mp-06.03_odp","label":"circumstances"}],"methods":[{"method":"examine","label":"MP-06(03)-Examine"},{"method":"interview","label":"MP-06(03)-Interview"},{"method":"test","label":"MP-06(03)-Test"}],"is_enhancement":true,"parent_id":"MP-6"},{"id":"MP-6(4)","oscal_id":"mp-6.4","family":"MP","title":"Controlled Unclassified Information","statement":"","is_enhancement":true,"parent_id":"MP-6"},{"id":"MP-6(5)","oscal_id":"mp-6.5","family":"MP","title":"Classified Information","statement":"","is_enhancement":true,"parent_id":"MP-6"},{"id":"MP-6(6)","oscal_id":"mp-6.6","family":"MP","title":"Media Destruction","statement":"","is_enhancement":true,"parent_id":"MP-6"},{"id":"MP-6(7)","oscal_id":"mp-6.7","family":"MP","title":"Dual Authorization","statement":"Enforce dual authorization for the sanitization of <system media>.","supplemental_guidance":"Organizations employ dual authorization to help ensure that system media sanitization cannot occur unless two technically qualified individuals conduct the designated task. Individuals who sanitize system media possess sufficient skills and expertise to determine if the proposed sanitization reflects applicable federal and organizational standards, policies, and procedures. Dual authorization also helps to ensure that sanitization occurs as intended, protecting against errors and false claims of having performed the sanitization actions. Dual authorization may also be known as two-person control. To reduce the risk of collusion, organizations consider rotating dual authorization duties to other individuals.","implementation_level":"organization","parameters":[{"id":"mp-06.07_odp","label":"system media"}],"methods":[{"method":"examine","label":"MP-06(07)-Examine"},{"method":"interview","label":"MP-06(07)-Interview"},{"method":"test","label":"MP-06(07)-Test"}],"related_controls":["AC-3","MP-2"],"is_enhancement":true,"parent_id":"MP-6"},{"id":"MP-6(8)","oscal_id":"mp-6.8","family":"MP","title":"Remote Purging or Wiping of Information","statement":"Provide the capability to purge or wipe information from <systems or system components> <organization-defined parameter>.","supplemental_guidance":"Remote purging or wiping of information protects information on organizational systems and system components if systems or components are obtained by unauthorized individuals. Remote purge or wipe commands require strong authentication to help mitigate the risk of unauthorized individuals purging or wiping the system, component, or device. The purge or wipe function can be implemented in a variety of ways, including by overwriting data or information multiple times or by destroying the key necessary to decrypt encrypted data.","implementation_level":"organization","parameters":[{"id":"mp-06.08_odp.01","label":"systems or system components"},{"id":"mp-06.08_odp.02","label":"","choices":["remotely","under {{ insert: param, mp-06.08_odp.03 }} "]},{"id":"mp-06.08_odp.03","label":"conditions"}],"methods":[{"method":"examine","label":"MP-06(08)-Examine"},{"method":"interview","label":"MP-06(08)-Interview"},{"method":"test","label":"MP-06(08)-Test"}],"is_enhancement":true,"parent_id":"MP-6"}]},{"id":"MP-7","oscal_id":"mp-7","family":"MP","title":"Media Use","statement":"a. <organization-defined parameter> the use of <types of system media> on <systems or system components> using <controls> ; and\nb. Prohibit the use of portable storage devices in organizational systems when such devices have no identifiable owner.","supplemental_guidance":"System media includes both digital and non-digital media. Digital media includes diskettes, magnetic tapes, flash drives, compact discs, digital versatile discs, and removable hard disk drives. Non-digital media includes paper and microfilm. Media use protections also apply to mobile devices with information storage capabilities. In contrast to [MP-2](#mp-2) , which restricts user access to media, MP-7 restricts the use of certain types of media on systems, for example, restricting or prohibiting the use of flash drives or external hard disk drives. Organizations use technical and nontechnical controls to restrict the use of system media. Organizations may restrict the use of portable storage devices, for example, by using physical cages on workstations to prohibit access to certain external ports or disabling or removing the ability to insert, read, or write to such devices. Organizations may also limit the use of portable storage devices to only approved devices, including devices provided by the organization, devices provided by other approved organizations, and devices that are not personally owned. Finally, organizations may restrict the use of portable storage devices based on the type of device, such as by prohibiting the use of writeable, portable storage devices and implementing this restriction by disabling or removing the capability to write to such devices. Requiring identifiable owners for storage devices reduces the risk of using such devices by allowing organizations to assign responsibility for addressing known vulnerabilities in the devices.","implementation_level":"organization","parameters":[{"id":"mp-07_odp.01","label":"types of system media"},{"id":"mp-07_odp.02","label":"","choices":["restrict","prohibit"]},{"id":"mp-07_odp.03","label":"systems or system components"},{"id":"mp-07_odp.04","label":"controls"}],"objectives":[{"id":"mp-7_obj.a","label":"MP-07a.","text":"the use of {{ insert: param, mp-07_odp.01 }} is {{ insert: param, mp-07_odp.02 }} on {{ insert: param, mp-07_odp.03 }} using {{ insert: param, mp-07_odp.04 }};"},{"id":"mp-7_obj.b","label":"MP-07b.","text":"the use of portable storage devices in organizational systems is prohibited when such devices have no identifiable owner."}],"methods":[{"method":"examine","label":"MP-07-Examine"},{"method":"interview","label":"MP-07-Interview"},{"method":"test","label":"MP-07-Test"}],"references":[{"title":"FIPS 199"},{"title":"SP 800-111"}],"related_controls":["AC-19","AC-20","PL-4","PM-12","SC-34","SC-41"],"enhancements":[{"id":"MP-7(1)","oscal_id":"mp-7.1","family":"MP","title":"Prohibit Use Without Owner","statement":"","is_enhancement":true,"parent_id":"MP-7"},{"id":"MP-7(2)","oscal_id":"mp-7.2","family":"MP","title":"Prohibit Use of Sanitization-resistant Media","statement":"Prohibit the use of sanitization-resistant media in organizational systems.","supplemental_guidance":"Sanitization resistance refers to how resistant media are to non-destructive sanitization techniques with respect to the capability to purge information from media. Certain types of media do not support sanitization commands, or if supported, the interfaces are not supported in a standardized way across these devices. Sanitization-resistant media includes compact flash, embedded flash on boards and devices, solid state drives, and USB removable media.","implementation_level":"organization","objectives":[{"id":"mp-7.2_obj-1","label":"MP-07(02)[01]","text":"sanitization-resistant media is identified;"},{"id":"mp-7.2_obj-2","label":"MP-07(02)[02]","text":"the use of sanitization-resistant media in organizational systems is prohibited."}],"methods":[{"method":"examine","label":"MP-07(02)-Examine"},{"method":"interview","label":"MP-07(02)-Interview"},{"method":"test","label":"MP-07(02)-Test"}],"related_controls":["MP-6"],"is_enhancement":true,"parent_id":"MP-7"}]},{"id":"MP-8","oscal_id":"mp-8","family":"MP","title":"Media Downgrading","statement":"a. Establish <system media downgrading process> that includes employing downgrading mechanisms with strength and integrity commensurate with the security category or classification of the information;\nb. Verify that the system media downgrading process is commensurate with the security category and/or classification level of the information to be removed and the access authorizations of the potential recipients of the downgraded information;\nc. Identify <system media requiring downgrading> ; and\nd. Downgrade the identified system media using the established process.","supplemental_guidance":"Media downgrading applies to digital and non-digital media subject to release outside of the organization, whether the media is considered removable or not. When applied to system media, the downgrading process removes information from the media, typically by security category or classification level, such that the information cannot be retrieved or reconstructed. Downgrading of media includes redacting information to enable wider release and distribution. Downgrading ensures that empty space on the media is devoid of information.","implementation_level":"organization","parameters":[{"id":"mp-08_odp.01","label":"system media downgrading process"},{"id":"mp-08_odp.02","label":"system media requiring downgrading"}],"objectives":[{"id":"mp-8_obj.a-1","label":"MP-08a.[01]","text":"a {{ insert: param, mp-08_odp.01 }} is established;"},{"id":"mp-8_obj.a-2","label":"MP-08a.[02]","text":"the {{ insert: param, mp-08_odp.01 }} includes employing downgrading mechanisms with strength and integrity commensurate with the security category or classification of the information;"},{"id":"mp-8_obj.b-1","label":"MP-08b.[01]","text":"there is verification that the system media downgrading process is commensurate with the security category and/or classification level of the information to be removed;"},{"id":"mp-8_obj.b-2","label":"MP-08b.[02]","text":"there is verification that the system media downgrading process is commensurate with the access authorizations of the potential recipients of the downgraded information;"},{"id":"mp-8_obj.c","label":"MP-08c.","text":"{{ insert: param, mp-08_odp.02 }} is identified;"},{"id":"mp-8_obj.d","label":"MP-08d.","text":"the identified system media is downgraded using the {{ insert: param, mp-08_odp.01 }}."}],"methods":[{"method":"examine","label":"MP-08-Examine"},{"method":"interview","label":"MP-08-Interview"},{"method":"test","label":"MP-08-Test"}],"references":[{"title":"32 CFR 2002"},{"title":"NSA MEDIA"}],"enhancements":[{"id":"MP-8(1)","oscal_id":"mp-8.1","family":"MP","title":"Documentation of Process","statement":"Document system media downgrading actions.","supplemental_guidance":"Organizations can document the media downgrading process by providing information, such as the downgrading technique employed, the identification number of the downgraded media, and the identity of the individual that authorized and/or performed the downgrading action.","implementation_level":"organization","methods":[{"method":"examine","label":"MP-08(01)-Examine"},{"method":"interview","label":"MP-08(01)-Interview"},{"method":"test","label":"MP-08(01)-Test"}],"is_enhancement":true,"parent_id":"MP-8"},{"id":"MP-8(2)","oscal_id":"mp-8.2","family":"MP","title":"Equipment Testing","statement":"Test downgrading equipment and procedures <organization-defined frequency> to ensure that downgrading actions are being achieved.","supplemental_guidance":"None.","implementation_level":"organization","parameters":[{"id":"mp-8.2_prm_1","label":"organization-defined frequency"},{"id":"mp-08.02_odp.01","label":"frequency"},{"id":"mp-08.02_odp.02","label":"frequency"}],"objectives":[{"id":"mp-8.2_obj-1","label":"MP-08(02)[01]","text":"downgrading equipment is tested {{ insert: param, mp-08.02_odp.01 }} to ensure that downgrading actions are being achieved;"},{"id":"mp-8.2_obj-2","label":"MP-08(02)[02]","text":"downgrading procedures are tested {{ insert: param, mp-08.02_odp.02 }} to ensure that downgrading actions are being achieved."}],"methods":[{"method":"examine","label":"MP-08(02)-Examine"},{"method":"interview","label":"MP-08(02)-Interview"},{"method":"test","label":"MP-08(02)-Test"}],"is_enhancement":true,"parent_id":"MP-8"},{"id":"MP-8(3)","oscal_id":"mp-8.3","family":"MP","title":"Controlled Unclassified Information","statement":"Downgrade system media containing controlled unclassified information prior to public release.","supplemental_guidance":"The downgrading of controlled unclassified information uses approved sanitization tools, techniques, and procedures.","implementation_level":"organization","objectives":[{"id":"mp-8.3_obj-1","label":"MP-08(03)[01]","text":"system media containing controlled unclassified information is identified;"},{"id":"mp-8.3_obj-2","label":"MP-08(03)[02]","text":"system media containing controlled unclassified information is downgraded prior to public release."}],"methods":[{"method":"examine","label":"MP-08(03)-Examine"},{"method":"interview","label":"MP-08(03)-Interview"},{"method":"test","label":"MP-08(03)-Test"}],"is_enhancement":true,"parent_id":"MP-8"},{"id":"MP-8(4)","oscal_id":"mp-8.4","family":"MP","title":"Classified Information","statement":"Downgrade system media containing classified information prior to release to individuals without required access authorizations.","supplemental_guidance":"Downgrading of classified information uses approved sanitization tools, techniques, and procedures to transfer information confirmed to be unclassified from classified systems to unclassified media.","implementation_level":"organization","objectives":[{"id":"mp-8.4_obj-1","label":"MP-08(04)[01]","text":"system media containing classified information is identified;"},{"id":"mp-8.4_obj-2","label":"MP-08(04)[02]","text":"system media containing classified information is downgraded prior to release to individuals without required access authorizations."}],"methods":[{"method":"examine","label":"MP-08(04)-Examine"},{"method":"interview","label":"MP-08(04)-Interview"},{"method":"test","label":"MP-08(04)-Test"}],"is_enhancement":true,"parent_id":"MP-8"}]}]};
